666	    /// Render the serial number as upper-case hex, matching the integer value
667	    /// (a DER sign-padding 0x00 byte is not part of the number).
668	    fn format_serial(content: &[u8]) -> Result<String, String> {
669	        if content.is_empty() {
670	            return Err("empty serial number".to_string());
671	        }
672	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
673	            return Err("non-minimal serial number encoding".to_string());
674	        }
675	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
676	            return Err("non-minimal serial number encoding".to_string());
677	        }
678	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
679	            return Err("negative serial number".to_string());
680	        }
681	        let digits = if content.len() > 1 && content[0] == 0x00 {
682	            &content[1..]
683	        } else {
684	            content
685	        };
686	        let mut s = String::with_capacity(digits.len() * 2);
687	        for b in digits {
688	            write!(s, "{b:02X}").unwrap();
689	        }
690	        if s.is_empty() {
691	            s.push_str("00");
692	        }
693	        Ok(s)
694	    }
