1	//! End-to-end regression tests for the validity-period (Not Before /
2	//! Not After) decoding and display behavior documented in README.md.
3	//!
4	//! Like `tests/name_display.rs`, these drive the real `chainview` binary so
5	//! the public contract is locked as a whole: on success the five fields keep
6	//! their fixed order, and malformed input means exit code 2, empty stdout and
7	//! the `chainview: invalid DER certificate:` stderr prefix with a non-empty
8	//! reason. Only time decoding is exercised here — signature verification,
9	//! trust and whether the certificate is currently expired are intentionally
10	//! out of scope: `inspect` displays fields, it never judges them.
11	//!
12	//! Coverage:
13	//! - `YYYY-MM-DDTHH:MM:SSZ` rendering for both UTCTime and GeneralizedTime;
14	//! - the UTCTime two-digit year pivot (<50 => 2000..2049, >=50 =>
15	//!   1950..1999), including the 49/50 boundary, and GeneralizedTime's
16	//!   four-digit years at and after 2050;
17	//! - the two time fields interpreting their own (possibly different)
18	//!   encodings independently;
19	//! - output independence from the local timezone;
20	//! - calendar validity (Gregorian leap years, range checks, no rollover)
21	//!   kept separate from expiry/not-yet-valid;
22	//! - strict textual form: mandatory seconds, trailing `Z`, no offsets,
23	//!   fractions, stray characters or other (non-time) tags, in either field.
24	//!
25	//! Certificates are built with the tiny zero-dependency DER constructor
26	//! copied below so individual time encodings can be crafted byte for byte.
27	
28	use std::fs;
29	use std::path::PathBuf;
30	use std::process::{Command, Output};
31	use std::sync::atomic::{AtomicU64, Ordering};
32	
33	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
34	const FIXED_SUBJECT: &str = "CN=example.com";
35	const FIXED_ISSUER: &str = "CN=Test CA";
36	
37	// ----- Known X.520 attribute OID arcs -------------------------------------
38	
39	const CN: &[u64] = &[2, 5, 4, 3];
40	
41	const TAG_UTC_TIME: u8 = 0x17;
42	const TAG_GENERALIZED_TIME: u8 = 0x18;
43	
44	// ----- Success: year pivot and encodings -----------------------------------
45	
46	#[test]
47	fn utctime_year_pivot_49_is_2049_and_50_is_1950() {
48	    // The boundary years must map by the fixed rule, never to an adjacent
49	    // year: 49 is 2049 (not 1949), 50 is 1950 (not 2050). A certificate may
50	    // have Not After before Not Before; validity windows are not judged.
51	    let cert = default_cert(
52	        &utc(b"490630120000Z"),
53	        &utc(b"500101000000Z"),
54	    );
55	    let (out, _cert) = run_inspect("utc-pivot-49-50", &cert);
56	    assert_times_success(&out, "2049-06-30T12:00:00Z", "1950-01-01T00:00:00Z");
57	
58	    // The other end of each half: 00 is 2000 and 99 is 1999.
59	    let cert = default_cert(
60	        &utc(b"000101000000Z"),
61	        &utc(b"991231235959Z"),
62	    );
63	    let (out, _cert) = run_inspect("utc-pivot-00-99", &cert);
64	    assert_times_success(&out, "2000-01-01T00:00:00Z", "1999-12-31T23:59:59Z");
65	}
