67	#[test]
68	fn generalized_time_keeps_four_digit_years_including_2050_and_beyond() {
69	    // GeneralizedTime is read literally as a four-digit year — there is no
70	    // pivot — so 2050 and later render correctly, and a fully written 1949
71	    // is not moved into 2049.
72	    let cert = default_cert(
