106	// ----- Success: timezone independence --------------------------------------
107	
108	#[test]
109	fn output_is_identical_in_every_local_timezone() {
110	    // The values are instants in UTC; the local zone (including date-line
111	    // offsets) must never shift the printed date or time. POSIX TZ strings
112	    // are used so the test needs no zoneinfo files: UTC-14 is fourteen hours
113	    // *ahead* of UTC, HST10 ten hours behind.
114	    let cert = default_cert(
115	        &utc(b"260115093000Z"),
116	        &utc(b"270115093000Z"),
117	    );
118	    let expected = format!(
119	        "Subject: {FIXED_SUBJECT}\n\
120	         Issuer: {FIXED_ISSUER}\n\
121	         Serial Number: {FIXED_SERIAL}\n\
122	         Not Before: 2026-01-15T09:30:00Z\n\
123	         Not After: 2027-01-15T09:30:00Z\n"
124	    );
125	
126	    let zones: &[Option<&str>] = &[
127	        None,
128	        Some(""),
129	        Some("UTC0"),
130	        Some("JST-9"),
131	        Some("IST-5:30"),
132	        Some("UTC-14"),
133	        Some("HST10"),
134	    ];
135	    for (i, zone) in zones.iter().enumerate() {
136	        let label = zone.map_or("unset", |z| if z.is_empty() { "empty" } else { z });
137	        let out = run_inspect_with_tz(&format!("tz-{i}"), &cert, *zone);
138	        assert_eq!(out.status.code(), Some(0), "zone {label}: stderr={}", lossy(&out.stderr));
139	        assert!(out.stderr.is_empty(), "zone {label}: stderr={}", lossy(&out.stderr));
140	        assert_eq!(
141	            lossy(&out.stdout),
142	            expected,
143	            "zone {label} shifted the output"
144	        );
145	    }
146	}
